const output = [];
for (const item of $input.all()) {
  const response = item.json;
  if (!Array.isArray(response.chunks)) throw new Error('Expected transcript search results. Inspect the search response.');
  for (const chunk of response.chunks) {
    if (typeof chunk.text !== 'string' || !chunk.video_id || !Number.isFinite(chunk.start_seconds)) throw new Error('A passage is missing its text, video ID or timestamp.');
    const watch = chunk.watch_url;
    if (typeof watch !== 'string' || !(/^\/watch\?/.test(watch) || /^https:\/\/arcmira\.com\/watch\?/.test(watch))) throw new Error('Unexpected source link. Inspect the search response.');
    output.push({json: {
      passage_id: chunk.id,
      topic: response.query,
      video_title: chunk.video_title,
      channel: chunk.channel_name,
      published_at: chunk.published_at,
      passage: chunk.text,
      start_seconds: chunk.start_seconds,
      youtube_url: 'https://www.youtube.com/watch?v=' + encodeURIComponent(chunk.video_id) + '&t=' + Math.floor(chunk.start_seconds) + 's',
      arcmira_url: watch.startsWith('/') ? 'https://arcmira.com' + watch : watch,
      speakers: (chunk.speakers || []).join('; '),
      transcript_source: chunk.source_label || chunk.source,
      coverage_note: response.note || '',
      search_index: JSON.stringify(response.search_index || {}),
      publication_window: JSON.stringify(response.window || {}),
      freshness: JSON.stringify(response.freshness || {}),
      checked_at: response.as_of || '',
      review_status: 'Needs review'
    }});
  }
}
if (!output.length) throw new Error('No passages matched. Review the search response and its coverage note before changing the topic or filters.');
return output;
